update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Ein Dekubitus ist eine lokal begrenzte Schädigung von Haut und darunterliegendem Gewebe, meist über einem Knochenvorsprung, verursacht durch Druck oder Druck in Verbindung mit Scherkräften. Er entsteht oft schon nach wenigen Stunden und ist in den meisten Fällen vermeidbar.", "tabelle": {"kopf": ["Kategorie (EPUAP/NPIAP)", "Merkmale"], "zeilen": [["Kategorie 1", "nicht wegdrückbare Rötung bei intakter Haut (Fingertest positiv)"], ["Kategorie 2", "Teilverlust der Haut: flaches, offenes Ulkus mit rosa Wundbett oder Blase"], ["Kategorie 3", "vollständiger Hautverlust, Fettgewebe sichtbar, Knochen, Sehnen und Muskeln nicht freiliegend"], ["Kategorie 4", "vollständiger Gewebeverlust mit freiliegendem Knochen, Sehnen oder Muskeln"], ["Keiner Kategorie zuordenbar", "Wundgrund durch Beläge oder Nekrose verdeckt, Tiefe unbekannt"], ["Vermutete tiefe Gewebeschädigung", "violette oder kastanienbraune Verfärbung bei intakter Haut oder blutgefüllte Blase"]]}, "einteilung": "Risikofaktoren: eingeschränkte Mobilität (wichtigster Faktor), Feuchtigkeit und Inkontinenz, Mangelernährung, Durchblutungsstörungen, Sensibilitätsstörungen, Fieber, hohes Alter, Sedierung.\nPrädilektionsstellen: Kreuzbein, Fersen, großer Rollhügel (Trochanter), Sitzbein, Hinterkopf, Ellenbogen, Ohrmuscheln.", "pruefungswissen": "Nach dem DNQP-Expertenstandard Dekubitusprophylaxe wird das Risiko systematisch eingeschätzt: zuerst durch fachliche Einschätzung, ergänzend mit Skalen wie Braden oder Norton. Bewegungsförderung und Positionswechsel werden individuell geplant, nicht nach starrem Zeitplan. Gerötete Haut darf nicht massiert werden.", "merksatz": "Druck weg, Bewegung her, Haut schützen, ernähren.", "pflegeschwerpunkt": "Haut täglich an den gefährdeten Stellen inspizieren (Fingertest), Bewegung fördern und Eigenbewegung unterstützen, Positionswechsel und Mikrolagerung, 30°-Seitenlage, Fersen freilagern, druckverteilende Hilfsmittel (z. B. Weichlagerungs- oder Wechseldruckmatratze) nach Einschätzung. Haut trocken halten, schonende Hautpflege, Scherkräfte beim Umlagern vermeiden (Lagerungshilfen, nicht ziehen). Ernährung und Flüssigkeit sichern. Keine Fell- oder Ringkissen, kein Föhnen oder Eisen. Befund dokumentieren, bei Wunden ab Kategorie 2 Wundmanagement nach Standard."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'DNQP-Expertenstandard Dekubitusprophylaxe in der Pflege; EPUAP/NPIAP/PPPIA-Leitlinie' where slug = 'dekubitus-vertieft';
update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Die Glasgow Coma Scale ist eine Skala zur schnellen und vergleichbaren Einschätzung der Bewusstseinslage. Bewertet werden drei Bereiche: Augen öffnen, verbale Reaktion und motorische Reaktion. Die Summe liegt zwischen 3 (keine Reaktion) und 15 (wach und orientiert).", "tabelle": {"kopf": ["Punkte", "Augen öffnen", "Verbale Reaktion", "Motorische Reaktion"], "zeilen": [["6", "–", "–", "befolgt Aufforderungen"], ["5", "–", "orientiert", "gezielte Abwehr auf Schmerzreiz"], ["4", "spontan", "verwirrt", "ungezielte Abwehr, Wegziehen"], ["3", "auf Ansprache", "unangemessene Worte", "Beugesynergismen (Beugen)"], ["2", "auf Schmerzreiz", "unverständliche Laute", "Strecksynergismen (Strecken)"], ["1", "keine Reaktion", "keine Reaktion", "keine Reaktion"]]}, "einteilung": "GCS 13–15 leichte, 9–12 mittelschwere, 3–8 schwere Bewusstseinsstörung bzw. Schädel-Hirn-Trauma.", "pruefungswissen": "Ab einem GCS von 8 oder darunter sind die Schutzreflexe meist nicht mehr sicher, deshalb besteht in der Regel die Indikation zur Atemwegssicherung (Intubation). Bei intubierten Patienten kann die verbale Reaktion nicht beurteilt werden und wird mit „T“ gekennzeichnet. Die GCS wird immer zusammen mit Pupillenkontrolle (Größe, Seitengleichheit, Lichtreaktion) und Vitalzeichen erhoben.", "merksatz": "Augen 4, Sprache 5, Motorik 6 – und ab 8 wird intubiert.", "pflegeschwerpunkt": "GCS in den angeordneten Abständen erheben und immer gleich vorgehen: erst ansprechen, dann berühren, dann einen definierten Schmerzreiz setzen (z. B. Druck auf den Trapeziusmuskel oder das Nagelbett). Jeweils die beste Reaktion werten. Werte im Verlauf dokumentieren und eine Verschlechterung um 2 oder mehr Punkte, neue Pupillendifferenz oder Krampfanfall sofort dem Arzt melden. Atemweg sichern, Aspiration vermeiden (Seitenlage bei Bewusstlosigkeit, wenn nicht intubiert)."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'Teasdale & Jennett (Glasgow Coma Scale); Leitlinie Schädel-Hirn-Trauma' where slug = 'gcs';
update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Beatmungsmodi legen fest, wie das Beatmungsgerät den Atemzug steuert: Wird ein Volumen oder ein Druck vorgegeben, und darf der Patient selbst mitatmen? Grob unterscheidet man kontrollierte, assistierte und spontane Formen. Ziel ist eine lungenschonende Beatmung und so früh wie möglich die Rückkehr zur Spontanatmung.", "tabelle": {"kopf": ["Modus", "Was wird vorgegeben", "Spontanatmung", "Typischer Einsatz"], "zeilen": [["VCV / IPPV (volumenkontrolliert)", "Atemzugvolumen und Frequenz; der Druck ergibt sich", "nein", "Narkose, tief sedierte Patienten"], ["PCV (druckkontrolliert)", "Beatmungsdruck und Frequenz; das Volumen ergibt sich", "nein", "lungenschonend, z. B. ARDS"], ["BIPAP / BiLevel", "zwei Druckniveaus im Wechsel", "ja, auf beiden Druckniveaus", "häufiger Standardmodus auf der Intensivstation"], ["SIMV", "feste Pflichtatemzüge, dazwischen Spontanatmung", "ja", "Entwöhnung (Weaning)"], ["PSV / ASB (Druckunterstützung)", "Druckunterstützung für jeden vom Patienten ausgelösten Atemzug", "ja, Patient bestimmt Frequenz", "Weaning, wache Patienten"], ["CPAP", "konstanter positiver Druck, keine Unterstützung", "ja, vollständig", "Weaning, Atemtraining, auch als Masken-CPAP"]]}, "einteilung": "Richtwerte: Atemzugvolumen 6–8 ml/kg ideales Körpergewicht (lungenprotektiv 6 ml/kg), Atemfrequenz 12–20/min, PEEP meist 5–10 cmH₂O, FiO₂ so niedrig wie möglich für die Zielsättigung, Plateaudruck möglichst ≤ 30 cmH₂O, Atemzeitverhältnis I:E meist 1:2.", "pruefungswissen": "Beim volumenkontrollierten Modus ist das Volumen sicher, aber der Druck kann gefährlich ansteigen. Beim druckkontrollierten Modus ist der Druck begrenzt, aber das Volumen schwankt mit Compliance und Resistance. Der PEEP hält die Alveolen am Ende der Ausatmung offen und verbessert die Oxygenierung.", "merksatz": "Volumen fix – Druck variabel, Druck fix – Volumen variabel.", "pflegeschwerpunkt": "Alarme ernst nehmen und Ursache suchen (z. B. Diskonnektion, Sekret, abgeknickter Schlauch), Tubuslage und Cuffdruck (ca. 20–30 cmH₂O) kontrollieren, Oberkörperhochlagerung 30–45° und Mundpflege zur Pneumonieprophylaxe, Absaugen nach Bedarf, Atemzugvolumen, Atemfrequenz, Spitzendruck und SpO₂ beobachten und dokumentieren. Ein Beatmungsbeutel mit Maske muss immer am Bett griffbereit sein."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'S3-Leitlinie Invasive Beatmung und Einsatz extrakorporaler Verfahren' where slug = 'beatmungsmodi';
update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Ein Pleuraerguss ist eine vermehrte Ansammlung von Flüssigkeit im Pleuraspalt zwischen Lungen- und Rippenfell. Normalerweise befinden sich dort nur wenige Milliliter. Größere Mengen drücken die Lunge zusammen und erschweren die Atmung.", "tabelle": {"kopf": ["", "Transsudat", "Exsudat"], "zeilen": [["Entstehung", "erhöhter Druck in den Gefäßen oder Eiweißmangel im Blut", "Entzündung oder Tumor, Gefäße werden durchlässiger"], ["Eiweißgehalt", "niedrig", "hoch"], ["Typische Ursachen", "Herzinsuffizienz (häufigste Ursache), Leberzirrhose, nephrotisches Syndrom", "Pneumonie (parapneumonisch), Tumoren, Lungenembolie, Tuberkulose"], ["Aussehen", "meist klar, hellgelb", "trüb, blutig oder eitrig (Empyem) möglich"]]}, "einteilung": "Ob Transsudat oder Exsudat, wird nach einer Pleurapunktion mit den Light-Kriterien bestimmt (Eiweiß- und LDH-Gehalt im Erguss im Verhältnis zum Blut).", "pruefungswissen": "Typische Zeichen sind Atemnot, atemabhängige Schmerzen und Reizhusten, bei der Untersuchung abgeschwächtes Atemgeräusch und gedämpfter Klopfschall. Nachgewiesen wird der Erguss vor allem mit Ultraschall und Röntgen. Behandelt wird die Ursache; große Ergüsse werden punktiert oder über eine Thoraxdrainage abgeleitet. Pro Punktion wird meist nur eine begrenzte Menge (etwa 1–1,5 Liter) abgelassen, um ein Reexpansionsödem zu vermeiden.", "merksatz": "Transsudat = Druck oder Eiweißmangel, Exsudat = Entzündung oder Tumor.", "pflegeschwerpunkt": "Oberkörper hochlagern, Atemfrequenz, SpO₂ und Atemnot beobachten, Sauerstoff nach Anordnung. Bei der Pleurapunktion assistieren: Patient sitzt vorgebeugt mit abgestützten Armen, steriles Arbeiten, Vitalzeichen überwachen. Danach auf zunehmende Atemnot, Husten, Brustschmerz oder Kreislaufprobleme achten (Pneumothorax, Reexpansionsödem) und sofort melden. Menge und Aussehen des Punktats dokumentieren."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'Light-Kriterien; Standardlehrbücher Innere Medizin' where slug = 'pleuraerguss';
update lerninhalte set daten = (daten - 'aufbau' - 'funktion' - 'physiologie' - 'klinische_relevanz' - 'wirkkette') || '{"definition": "Ein Delir ist eine akut einsetzende, im Tagesverlauf schwankende Störung von Aufmerksamkeit, Bewusstsein und Denken. Es ist ein medizinischer Notfall mit körperlicher Ursache, wird aber häufig übersehen, vor allem in der stillen, hypoaktiven Form.", "tabelle": {"kopf": ["", "Delir", "Demenz"], "zeilen": [["Beginn", "plötzlich, Stunden bis Tage", "schleichend, Monate bis Jahre"], ["Verlauf", "schwankend, oft nachts schlechter", "langsam fortschreitend"], ["Aufmerksamkeit", "deutlich gestört", "anfangs meist erhalten"], ["Bewusstsein", "verändert (unruhig oder schläfrig)", "meist klar"], ["Behandelbarkeit", "oft rückbildungsfähig, wenn die Ursache behandelt wird", "nicht heilbar"]]}, "einteilung": "Hyperaktives Delir: Unruhe, Agitation, Halluzinationen, Nesteln, Weglauftendenz.\nHypoaktives Delir: Antriebsarmut, Schläfrigkeit, Verlangsamung – die häufigste und am meisten übersehene Form.\nGemischtes Delir: Wechsel zwischen beiden Formen.", "pruefungswissen": "Risikofaktoren sind hohes Alter, vorbestehende Demenz, Operationen, Infektionen, Schmerzen, Flüssigkeitsmangel, Schlafmangel, Harnverhalt, Obstipation, Alkoholentzug und Medikamente (z. B. anticholinerg wirksame Mittel, Benzodiazepine). Zum Erkennen gibt es Screening-Instrumente wie 4AT, CAM bzw. auf der Intensivstation CAM-ICU zusammen mit der RASS. Eine Demenz erhöht das Delirrisiko, beides kann gleichzeitig vorliegen.", "merksatz": "Plötzlich verwirrt ist ein Delir, bis das Gegenteil bewiesen ist.", "pflegeschwerpunkt": "Veränderungen früh erkennen und melden, regelmäßig screenen. Nicht-medikamentöse Maßnahmen stehen an erster Stelle: Orientierung geben (Uhr, Kalender, Namen nennen), Brille und Hörgerät einsetzen, Tag-Nacht-Rhythmus und Schlaf fördern, früh mobilisieren, Angehörige einbeziehen, auf Trinkmenge, Ausscheidung und Schmerzen achten, Reize und Geräusche reduzieren. Fixierungen möglichst vermeiden. Medikamente nur nach ärztlicher Anordnung."}'::jsonb, stand = current_date, geprueft_von = 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', geprueft_am = current_date, quelle = 'S3-Leitlinie Analgesie, Sedierung und Delirmanagement in der Intensivmedizin (DAS); 4AT/CAM' where slug = 'delir';
