insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-herzinsuffizienz', 'Pflegeplanung Herzinsuffizienz', '{"definition": "Unfähigkeit des Herzens, ausreichend Blut/Sauerstoff zu pumpen. Einteilung: Links-, Rechts- oder Globalinsuffizienz. NYHA-Stadien I–IV.", "symptome": "Dyspnoe (Belastung → Ruhe); Orthopnoe (flach liegen nicht möglich); Ödeme (Knöchel, Unterschenkel); Nykturie; Müdigkeit, Leistungsminderung; Zyanose; Gewichtszunahme durch Wassereinlagerung; Tachykardie", "pflegeplanung": [{"problem": "Beeinträchtigte kardiopulmonale Gewebeperfusion infolge verminderter Herzleistung, erkennbar an Dyspnoe, Zyanose, SpO₂ < 94%", "ressourcen": ["Kooperativ", "Versteht Anweisungen", "Angehörige unterstützend"], "ziel": "Patient atmet in Ruhe ohne Dyspnoe (NRS Atemnot 0-2) innerhalb von 48h", "massnahmen": ["Oberkörperhochlagerung 30-45° kontinuierlich", "O₂-Gabe nach Anordnung, SpO₂ ≥ 94% sichern", "Vitalzeichen 4-stündlich: RR, HF, AF, SpO₂", "Flüssigkeitsbilanz (Ein-/Ausfuhr täglich)", "Tägliche Gewichtskontrolle (gleiche Zeit, Waage)", "Ödeme dokumentieren (Umfang messen)", "Aktivität schrittweise steigern nach Befinden"], "evaluation": "Täglich: Dyspnoe-NRS, SpO₂, Gewicht, Ödeme"}, {"problem": "Überschuss an Körperflüssigkeit infolge Herzpumpversagen, erkennbar an Ödemen, Gewichtszunahme 3kg/Woche", "ressourcen": ["Versteht Bedeutung der Trinkmengenbeschränkung"], "ziel": "Gewichtsreduktion um 0,5-1kg/Tag durch Diurese, Ödeme rückläufig nach 3 Tagen", "massnahmen": ["Trinkmengenbeschränkung nach Anordnung (meist 1,5-2L/Tag)", "Diuretika pünktlich verabreichen, Wirkung dokumentieren", "Natriumarme Ernährung besprechen", "Hautpflege ödematöser Extremitäten (Druckgefahr!)", "Hochlagerung der Beine", "Patient über Selbstkontrolle schulen (Tagesgewicht)"], "evaluation": "Täglich Gewicht, Bilanz, Ödemstatus"}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": [{"frage": "Was bedeutet NYHA III bei Herzinsuffizienz?", "optionen": ["Keine Symptome", "Symptome bei leichter Belastung", "Symptome bei stärkerer Belastung", "Symptome in Ruhe"], "richtig": 1}, {"frage": "Welche Lagerung ist bei akuter kardialer Dyspnoe indiziert?", "optionen": ["Flachlagerung", "Oberkörperhochlagerung 30-45°", "Bauchlagerung", "Linksseitenlage"], "richtig": 1}, {"frage": "Was ist das wichtigste Pflegemonitoring bei Herzinsuffizienz?", "optionen": ["Temperatur", "Tägliche Gewichtskontrolle + Flüssigkeitsbilanz", "Pupillenkontrolle", "Blutzucker"], "richtig": 1}], "haeufige_pruefungsfrage": "Was bedeutet NYHA III bei Herzinsuffizienz?"}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-herzinsuffizienz');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-copd', 'Pflegeplanung COPD', '{"definition": "Chronisch obstruktive Lungenerkrankung. Nicht vollständig reversible Atemwegsobstruktion durch chronische Bronchitis + Lungenemphysem. Hauptursache: Rauchen. GOLD-Stadien I–IV.", "symptome": "Chronischer Husten (Raucherhusten); Auswurf (morgens besonders); Belastungsdyspnoe (progredient); Giemen/Brummen; Fassthorax (Emphysem); Lippenzyanose; Uhrglasnägel; Trommelschlägelfinger", "pflegeplanung": [{"problem": "Ineffektives Atemmuster infolge bronchialer Obstruktion, erkennbar an Dyspnoe NRS 6, AF 26/min, SpO₂ 88%", "ressourcen": ["Kann Lippenbremse anwenden", "Motiviert zur Mitarbeit"], "ziel": "SpO₂ ≥ 90% (COPD-Ziel!), Dyspnoe NRS ≤ 3 nach 24h", "massnahmen": ["O₂-Gabe VORSICHTIG: Ziel SpO₂ 88-92% (nicht höher! Atemantriebreduktion!)", "Kutschersitz anleiten (sitzend, Arme aufgestützt → Atemhilfsmuskulatur)", "Lippenbremse üben und anwenden", "Bronchodilatator-Inhalation nach Anordnung, Technik kontrollieren", "Sekretmobilisation: atemunterstützende Lagerung, PEP-Geräte", "Atemgymnastik 3x täglich", "Körperliche Schonung, Aktivität nach Befinden"], "evaluation": "4-stündlich SpO₂, AF, Dyspnoe-NRS"}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": [{"frage": "Warum darf COPD-Patienten NICHT unkontrolliert hochdosiert O₂ gegeben werden?", "optionen": ["O₂ ist zu teuer", "Hypoxischer Atemantrieb: zu viel O₂ → Atemdepression", "O₂ verschlimmert Bronchitis", "Keine Kontraindikation"], "richtig": 1}, {"frage": "Was ist der Kutschersitz bei Dyspnoe?", "optionen": ["Flachlagerung", "Sitzend, Arme auf Oberschenkeln/Tisch aufgestützt – entlastet Atemhilfsmuskulatur", "Linksseitenlage", "Stehend an Wand gelehnt"], "richtig": 1}, {"frage": "Was ist die Lippenbremse?", "optionen": ["Medikament", "Atemtechnik: Ausatmung durch halb geöffnete Lippen – erhöht Atemwegsdruck → verhindert Bronchiolenkollaps", "Eine Lagerungstechnik", "Ein Absaugverfahren"], "richtig": 1}], "haeufige_pruefungsfrage": "Warum darf COPD-Patienten NICHT unkontrolliert hochdosiert O₂ gegeben werden?"}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-copd');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-diabetes-typ-2', 'Pflegeplanung Diabetes mellitus Typ 2', '{"definition": "Chronische Stoffwechselerkrankung mit Insulinresistenz und relativem Insulinmangel. Häufigste Diabetesform (90%). Risikofaktoren: Adipositas, Bewegungsmangel, genetische Disposition.", "symptome": "Polyurie, Polydipsie (bei Entgleisung); Müdigkeit, Leistungsminderung; Wundheilungsstörungen; Häufige Infektionen; Sehstörungen (Retinopathie); Kribbeln/Taubheit Füße (Neuropathie); Oft lange symptomlos!", "pflegeplanung": [{"problem": "Risiko für Hypoglykämie infolge Insulintherapie und unregelmäßiger Nahrungsaufnahme", "ressourcen": ["Erkennt Hypoglykämie-Zeichen", "Kann BZ selbst messen"], "ziel": "Keine Hypoglykämie-Episode (BZ > 70 mg/dl) während des stationären Aufenthalts", "massnahmen": ["BZ-Kontrolle nach Anordnung (nüchtern, vor/nach Mahlzeiten)", "Mahlzeiten pünktlich, Insulin zeitgerecht verabreichen (6-R-Regel!)", "Hypoglykämie-Schema beachten: BZ < 70 → 20g KH oral (Traubenzucker)", "BZ < 50 oder bewusstlos → Glukose 40% i.v. nach Anordnung", "Notfallset: Glukose immer griffbereit", "Schulung: Symptome Hypoglykämie (Zittern, Schwitzen, Herzrasen, Verwirrtheit)"], "evaluation": "BZ-Profil täglich, Hypoglykämie-Ereignisse dokumentieren"}, {"problem": "Beeinträchtigte Gewebeintegrität infolge Wundheilungsstörung bei diabetischer Polyneuropathie, erkennbar an Ulcus plantare rechts", "ressourcen": ["Kooperativ", "Familie unterstützt Verbandswechsel"], "ziel": "Wunde zeigt nach 7 Tagen Granulationsgewebe, keine Infektzeichen", "massnahmen": ["Tägliche Wundinspektion und Dokumentation (Foto, Maße, Exsudat, Geruch)", "Verbandswechsel nach Wundexpertenstandard (feuchte Wundversorgung)", "Druckentlastung: kein Druck auf Ulcus (Spezialschuhe, Bettung)", "BZ-Einstellung optimieren (schlechte BZ → schlechte Wundheilung)", "Fußpflege täglich: Inspektion alle Zehenzwischenräume", "Fußwärme nicht mit Wärmflasche/Heizkissen! (Neuropathie = kein Temperaturempfinden)"], "evaluation": "Täglich: Wunddokumentation, BZ-Verlauf"}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": [{"frage": "Welche Pflegemaßnahme hat bei Hypoglykämie (BZ < 70 mg/dl, Patient wach) höchste Priorität?", "optionen": ["Sofort Insulin geben", "20g schnell resorbierbare Kohlenhydrate oral (Traubenzucker, Fruchtsaft)", "Patient schlafen lassen", "Blutabnahme"], "richtig": 1}, {"frage": "Was ist das Diabetische Fußsyndrom (DFS) und welche Pflegemaßnahme ist FALSCH?", "optionen": ["Täglich Füße inspizieren", "Wärmflasche bei kalten Füßen anwenden", "Druckentlastung sicherstellen", "Feuchte Wundversorgung"], "richtig": 1}, {"frage": "Was ist HbA1c und was zeigt er?", "optionen": ["Aktueller Blutzucker", "Durchschnittlicher Blutzucker der letzten 2-3 Monate (Langzeitblutzucker)", "Insulinspiegel", "Ketonkörper"], "richtig": 1}], "haeufige_pruefungsfrage": "Welche Pflegemaßnahme hat bei Hypoglykämie (BZ < 70 mg/dl, Patient wach) höchste Priorität?"}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-diabetes-typ-2');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-schlaganfall', 'Pflegeplanung Schlaganfall (Apoplex)', '{"definition": "Plötzliche fokale Hirnschädigung durch Ischämie (85%, I63) oder Blutung (15%, I61). Time is Brain: jede Minute = 1,9 Mio. Neuronenverluste. Thrombolyse-Fenster: 4,5h (ischämisch).", "symptome": "Plötzliche einseitige Lähmung (Hemiparese/-plegie); Gesichtslähmung (faziale Parese); Sprach-/Sprechstörung (Aphasie/Dysarthrie); Schluckstörung (Dysphagie); Sehstörungen (Hemianopsie); Schwindel, Gangstörung; Starke Kopfschmerzen (bei Blutung); Bewusstlosigkeit", "pflegeplanung": [{"problem": "Risiko Aspiration infolge Schluckstörung (Dysphagie) nach Schlaganfall, erkennbar an positivem Dysphagie-Screening", "ressourcen": ["Patient kooperiert trotz Aphasie", "Logopädie verfügbar"], "ziel": "Patient aspiriert nicht – sichere Nahrungsaufnahme durch angepasste Konsistenz nach logopädischer Freigabe", "massnahmen": ["Vor ERSTEM Schluck: standardisiertes Dysphagie-Screening (z.B. 3-Unzen-Wassertest)", "Bis Screening-Ergebnis: NICHTS per oral, Mund feucht halten", "Nach Logo-Freigabe: angepasste Kost (Andickungsmittel, weiche Kost)", "Beim Essen: aufrechte Position 90°, betroffene Seite unterstützen", "Essen nie überstürzen, genug Zeit lassen", "Absauggerät bereithalten", "Nach Essen 30 Min. aufrecht bleiben", "Angehörige in sicheres Füttern schulen"], "evaluation": "Täglich Schluckfähigkeit beobachten, Aspirationszeichen (Husten, Stimmveränderung)"}, {"problem": "Beeinträchtigte körperliche Mobilität infolge Hemiparese links, erkennbar daran, dass der linke Arm und das linke Bein nicht angehoben werden können", "ressourcen": ["Hohe Motivation", "Vorhandenes Pflegebett mit Hilfsmitteln"], "ziel": "Patient dreht sich mit geringer Hilfe auf betroffene Seite nach 3 Tagen Frührehabilitation", "massnahmen": ["Bobath-Lagerung: betroffene Seite einbeziehen, nicht kompensieren", "Stundenlageplan: alle 2h Umlagerung", "Patient von betroffener Seite ansprechen (Förderung Aufmerksamkeit zur Seite)", "Frührehabilitation: Physiotherapie ab Tag 1 nach Anordnung", "Transfertraining (Bett → Stuhl) mit PT", "Hilfsmittel: Rollator, Handschiene nach Ergotherapie", "Antispastik-Lagerung beachten (Armschiene)"], "evaluation": "Täglich Motorik, Tonus, Lagerungstoleranz"}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": [{"frage": "Was bedeutet FAST beim Schlaganfall?", "optionen": ["Ein Medikament", "F=Face, A=Arms, S=Speech, T=Time – Schlaganfall-Schnelltest, sofort 112!", "Ein Bildgebungsverfahren", "Eine Lagerungstechnik"], "richtig": 1}, {"frage": "Warum muss vor dem ersten Schluck ein Dysphagie-Screening erfolgen?", "optionen": ["Nur Routine", "Stille Aspiration möglich: Patient schluckt und hustet nicht – Pneumonie- und Asphyxie-Risiko!", "Nur bei Bewusstlosen", "Nur bei Beatmeten"], "richtig": 1}, {"frage": "Was ist das Bobath-Konzept bei der Schlaganfallpflege?", "optionen": ["Bettruhe", "Betroffene Körperseite aktiv einbeziehen, nicht kompensieren – fördert Neuroplastizität und verhindert Vernachlässigung", "Nur für Physiotherapeuten", "Schmerztherapiekonzept"], "richtig": 1}], "haeufige_pruefungsfrage": "Was bedeutet FAST beim Schlaganfall?"}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-schlaganfall');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-pneumonie', 'Pflegeplanung Pneumonie', '{"definition": "Akute Entzündung des Lungenparenchyms, meist bakteriell (häufig Pneumokokken) oder viral. Ambulant oder nosokomial erworben.", "symptome": "Fieber, Schüttelfrost; Husten mit Auswurf; Dyspnoe, Tachypnoe; Atemabhängige thorakale Schmerzen; Abgeschlagenheit; Bei älteren Menschen oft Verwirrtheit", "pflegeplanung": [{"problem": "Beeinträchtigter Gasaustausch infolge Lungeninfiltration, erkennbar an Dyspnoe, Tachypnoe, SpO₂-Abfall", "ressourcen": ["Patient kooperativ bei Atemübungen", "Motiviert zu mobilisieren"], "ziel": "Patient zeigt innerhalb von 48 h SpO₂ ≥ 94 % und reduzierte Atemarbeit", "massnahmen": ["O₂ nach AO, SpO₂/Atemfrequenz überwachen", "Oberkörperhochlagerung, Atemtherapie anleiten", "Sekretmobilisation, abhusten lassen, ausreichend Flüssigkeit", "Antibiotika/Antipyrese nach AO", "Frühmobilisation und Pneumonieprophylaxe"], "evaluation": "SpO₂ stabil, Atemarbeit reduziert, Fieber rückläufig."}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": []}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-pneumonie');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-demenz', 'Pflegeplanung Demenz', '{"definition": "Fortschreitender Verlust kognitiver Fähigkeiten (v. a. Gedächtnis), häufigste Form ist Alzheimer. Beeinträchtigt Alltag und Selbstständigkeit zunehmend.", "symptome": "Gedächtnisstörungen (v. a. Kurzzeitgedächtnis); Orientierungsstörungen (Zeit/Ort); Wortfindungs-/Sprachstörungen; Beeinträchtigte Alltagskompetenz; Verhaltensänderungen, Unruhe, Tag-Nacht-Umkehr", "pflegeplanung": [{"problem": "Beeinträchtigte Orientierung und Selbstständigkeit infolge Demenz, erkennbar an Gedächtnis-/Orientierungsstörungen, Unruhe", "ressourcen": ["Biografie bekannt", "Angehörige unterstützen", "Erhaltene Ressourcen"], "ziel": "Der Mensch mit Demenz ist sicher, orientiert sich im Rahmen seiner Möglichkeiten und behält Selbstständigkeit/Würde", "massnahmen": ["Klare Tagesstruktur, Orientierungshilfen, vertraute Routinen", "Validierender, ruhiger Umgang, einfache Kommunikation", "Sicherheit gewährleisten (Sturz-/Hinlaufprophylaxe), reizarm", "Ressourcen/Selbstständigkeit fördern, Biografiearbeit", "Ernährung/Flüssigkeit sichern, Angehörige beraten/entlasten"], "evaluation": "Sicher, im Rahmen orientiert, Selbstständigkeit/Würde gewahrt."}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": []}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-demenz');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-hueft-tep', 'Pflegeplanung Hüft-TEP und Knie-TEP', '{"definition": "Totalendoprothese der Hüfte (Hüft-TEP) oder des Knies (Knie-TEP). Häufigste elektive Orthopädie-Operation. Ziel: Schmerzfreiheit und Beweglichkeit wiederherstellen.", "symptome": "Postoperativ: Schmerzen, Schwellung; Bewegungseinschränkung; Luxationsgefahr (Hüft-TEP!); Thrombosegefahr", "pflegeplanung": [{"problem": "Risiko der Hüft-TEP-Luxation infolge postoperativer Instabilität (Erstmobilisation ab Tag 1)", "ressourcen": ["Versteht Luxationsprophylaxe", "Kooperativ"], "ziel": "Keine Luxation während des stationären Aufenthalts, Patient kennt Verbotspositionen nach Entlassung", "massnahmen": ["Verbotspositionen einhalten: kein Beugen > 90°, kein Überkreuzen der Beine, kein Drehen des Fußes nach innen", "Lagerungskeil zwischen die Beine (Abduktionskeil)", "Transfer immer auf operierte Seite, Anleitung bei jedem Transfer", "Toilettenerhöhung, erhöhte Sitzmöbel (Beugewinkel < 90°)", "Patient und Angehörige in Verbotspositionen schulen", "Physio: Gangschulung mit Gehstützen"], "evaluation": "Täglich Transfer kontrollieren, Patientenwissen überprüfen"}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": [{"frage": "Welche Lagerung ist nach Hüft-TEP zwingend einzuhalten?", "optionen": ["Beine überkreuzen erlaubt", "Abduktionskeil zwischen die Beine, kein Beugen > 90°, keine Innenrotation", "Bauchlagerung", "Beine eng zusammenhalten"], "richtig": 1}, {"frage": "Warum ist Thromboseprophylaxe nach Knie-/Hüft-TEP besonders wichtig?", "optionen": ["Standard bei jedem OP", "Hohe TVT-Rate (bis 40% ohne Prophylaxe) durch Blutstase und Gefäßverletzung", "Nur bei übergewichtigen Patienten", "Nur bei älteren Patienten"], "richtig": 1}, {"frage": "Was ist bei der Mobilisation nach Knie-TEP zu beachten?", "optionen": ["Erst nach 1 Woche mobilisieren", "Frühmobilisation ab Tag 1 mit Physio, Vollbelastung sofort erlaubt je nach Fixation", "Bettruhe 3 Wochen", "Nur passive Bewegung"], "richtig": 1}], "haeufige_pruefungsfrage": "Welche Lagerung ist nach Hüft-TEP zwingend einzuhalten?"}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-hueft-tep');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-schenkelhalsfraktur', 'Pflegeplanung Schenkelhalsfraktur', '{"definition": "Bruch des proximalen Oberschenkels, häufig bei älteren Menschen nach Sturz (Osteoporose). Hohe Bedeutung wegen Immobilität und Komplikationen.", "symptome": "Schmerzhafte Bewegungseinschränkung der Hüfte; Bein verkürzt und außenrotiert; Belastungsunfähigkeit; Schwellung/Hämatom; Sturzanamnese", "pflegeplanung": [{"problem": "Beeinträchtigte Mobilität infolge proximaler Femurfraktur und postoperativen Zustands, erkennbar an Schmerz, Belastungseinschränkung", "ressourcen": ["Motiviert mitzuarbeiten", "Angehörige unterstützen", "Vor Sturz selbstständig mobil"], "ziel": "Patient mobilisiert in den ersten postoperativen Tagen nach AO schmerzarm (NRS ≤ 3) mit Hilfsmittel", "massnahmen": ["Schmerzmanagement nach AO, vor Mobilisation analgetisch abdecken", "Frühmobilisation nach ärztlicher Freigabe, Physiotherapie einbeziehen", "Thrombose-, Pneumonie- und Dekubitusprophylaxe konsequent", "Durchblutung/Sensomotorik/Wundkontrolle dokumentieren", "Sturzprophylaxe, Hilfsmittel bereitstellen"], "evaluation": "Schmerzarme Mobilisation gelingt, keine prophylaxeassoziierten Komplikationen."}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": []}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-schenkelhalsfraktur');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-parkinson', 'Pflegeplanung Morbus Parkinson', '{"definition": "Chronisch-neurodegenerative Erkrankung mit Dopaminmangel. Leitsymptome: Rigor, Tremor, Brady-/Akinese, posturale Instabilität.", "symptome": "Ruhetremor; Rigor (Muskelsteifigkeit); Bradykinese/Akinese (verlangsamte Bewegung); Posturale Instabilität, kleinschrittiger Gang; Maskengesicht, leise Sprache, Mikrografie", "pflegeplanung": [{"problem": "Sturzgefahr und beeinträchtigte Mobilität infolge Parkinson, erkennbar an Rigor, Bradykinese, posturaler Instabilität", "ressourcen": ["Motiviert", "Angehörige unterstützen", "Physiotherapie verfügbar"], "ziel": "Der Patient bleibt sturzfrei und so mobil/selbstständig wie möglich", "massnahmen": ["Medikamente exakt pünktlich nach AO, On-/Off-Phasen beobachten", "Sturzprophylaxe, sichere Mobilisation, Hilfsmittel", "Zeit lassen, Selbstständigkeit fördern", "Schluckstörung/Aspiration beachten, Ernährung anpassen", "Obstipations-/Dekubitusprophylaxe, Physiotherapie einbinden"], "evaluation": "Sturzfrei, Mobilität/Selbstständigkeit erhalten, Medikamentenwirkung stabil."}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": []}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-parkinson');
insert into lerninhalte (typ, kategorie, slug, titel, daten, quelle, stand, geprueft_von, geprueft_am) select 'grundlagen', 'Pflegeplanung', 'pflegeplanung-asthma-kind', 'Pflegeplanung Asthma bronchiale bei Kindern', '{"definition": "Chronisch-entzündliche Atemwegserkrankung mit variabler, reversibler Obstruktion und bronchialer Hyperreagibilität; anfallsartige Atemnot.", "symptome": "Anfallsartige Atemnot; Exspiratorisches Giemen, verlängertes Exspirium; Trockener Husten (oft nachts); Engegefühl in der Brust; Bei schwerem Anfall: Sprechdyspnoe, Einziehungen, Tachykardie", "pflegeplanung": [{"problem": "Beeinträchtigte Atmung infolge bronchialer Obstruktion, erkennbar an Giemen, verlängertem Exspirium, Dyspnoe", "ressourcen": ["Kind kennt seine Inhalation", "Eltern unterstützend", "Bekannte Trigger"], "ziel": "Kind atmet innerhalb von 1 h ruhiger, Giemen rückläufig, SpO₂ ≥ 94 %", "massnahmen": ["Atemerleichternde Lagerung (Kutschersitz), Ruhe", "Inhalative Bronchodilatatoren nach AO mit Spacer", "SpO₂/Atemfrequenz/Atemarbeit engmaschig", "Steroide nach AO bei mittlerem/schwerem Anfall", "Kind und Eltern anleiten, Trigger meiden"], "evaluation": "Dyspnoe und Giemen rückläufig, SpO₂ stabil, Kind ruhig."}], "pruefungswissen": "Eine Pflegeplanung folgt dem Pflegeprozess: Pflegeproblem mit Ursache und Anzeichen (PESR-Schema), Ressourcen, ein messbares Pflegeziel (SMART), konkrete Maßnahmen und die Evaluation, ob das Ziel erreicht wurde. Die Beispiele hier sind Muster und müssen immer an den einzelnen Menschen angepasst werden.", "merksatz": "Problem – Ressource – Ziel – Maßnahme – Evaluation.", "mcq": []}'::jsonb, 'Pflegeprozess nach Fiechter/Meier; PESR-Schema; Krankheitsbilder in PLAN', current_date, 'Patrick Schenkelberger, Fachpfleger Anästhesie und Intensivmedizin', current_date where not exists (select 1 from lerninhalte where slug = 'pflegeplanung-asthma-kind');
